const key = 'quittances-v1';
const euro = n => new Intl.NumberFormat('fr-FR', {style:'currency', currency:'EUR'}).format(n || 0);
const monthLabel = m => new Intl.DateTimeFormat('fr-FR', {month:'long', year:'numeric'}).format(new Date(`${m}-01T12:00:00`));
const isoToday = () => new Date().toISOString().slice(0,10);
let state = JSON.parse(localStorage.getItem(key) || 'null') || {settings:{year:new Date().getFullYear(),start:'',rent:0,charges:0,coefficient:100},months:[],payments:[]};
function save(){ localStorage.setItem(key, JSON.stringify(state)); }
function backupFileName(){ return `quittances-sauvegarde-${new Date().toISOString().replace(/[-:]/g,'').replace(/\..+/, '')}.json`; }
function storeSettingsForm(){ const next=Object.fromEntries(new FormData(document.querySelector('#settings'))); state.settings={...next,rent:+next.rent||0,charges:+next.charges||0,coefficient:+next.coefficient||100}; }
function downloadBackup(){ storeSettingsForm(); save(); const content=JSON.stringify({format:'quittances-backup',version:1,savedAt:new Date().toISOString(),data:state},null,2); const link=document.createElement('a'); link.href=URL.createObjectURL(new Blob([content],{type:'application/json'})); link.download=backupFileName(); link.click(); URL.revokeObjectURL(link.href); }
function dates(){ const {year,start}=state.settings; if(!year) return []; const now=new Date(), limit=`${Math.min(+year,now.getFullYear())}-${String(now.getMonth()+1).padStart(2,'0')}`; let cursor=start ? start.slice(0,7) : `${year}-01`; if(cursor.slice(0,4)!==String(year)) cursor=`${year}-01`; const result=[]; while(cursor<=limit){ result.push(cursor); const [y,m]=cursor.split('-').map(Number); cursor=`${m===12?y+1:y}-${String(m===12?1:m+1).padStart(2,'0')}`; } return result; }
function scheduled(month){ const changed=state.months.find(x=>x.month===month), base=state.settings; const value=changed || {rent:base.rent,charges:base.charges,coefficient:base.coefficient}; return {...value, month, rent:+value.rent||0, charges:+value.charges||0, coefficient:+value.coefficient||0, total:((+value.rent||0)+(+value.charges||0))*(+value.coefficient||0)/100}; }
function paymentsFor(month){ return state.payments.filter(p=>p.month===month); }
function paid(month, source){ return paymentsFor(month).filter(p=>!source || p.source===source).reduce((sum,p)=>sum+(+p.amount||0),0); }
function cumulative(values){ let total=0; return values.map(value=>(total+=value,total)); }
function setMonthCoefficient(month, coefficient){ const base=scheduled(month); state.months=state.months.filter(x=>x.month!==month); state.months.push({month,rent:base.rent,charges:base.charges,coefficient:+coefficient||0}); save(); render(); }
function render(){ document.querySelector('#today').textContent=new Intl.DateTimeFormat('fr-FR',{dateStyle:'long'}).format(new Date()); for(const [name,value] of Object.entries(state.settings)){ const input=document.querySelector(`[name="${name}"]`); if(input) input.value=value ?? ''; } const ds=dates(), dueByMonth=ds.map(m=>scheduled(m).total), paidByMonth=ds.map(m=>paid(m)); const dueCumulative=cumulative(dueByMonth), paidCumulative=cumulative(paidByMonth); const dueTotal=dueCumulative.at(-1)||0, paidTotal=paidCumulative.at(-1)||0; let receipt='—'; for(let i=0;i<ds.length;i++){ if(paidTotal>=dueCumulative[i]) receipt=ds[i]; else break; } document.querySelector('#summary').innerHTML=[['Total dû à ce jour',euro(dueTotal)],['Total versé',euro(paidTotal)],['Reste dû',euro(Math.max(0,dueTotal-paidTotal))],['Mois de quittance',receipt==='—'?'Aucun':monthLabel(receipt)]].map((item,index)=>`<article class="card ${index===2&&dueTotal-paidTotal>0?'alert':''}"><span>${item[0]}</span><strong>${item[1]}</strong></article>`).join(''); document.querySelector('#months').innerHTML=ds.map((month,index)=>{const x=scheduled(month);return `<tr><td>${monthLabel(month)}</td><td class="money">${euro(x.rent)}</td><td class="money">${euro(x.charges)}</td><td><input class="coefficient-input" type="number" min="0" max="100" step="0.01" value="${x.coefficient}" data-month="${month}" aria-label="Coefficient d’occupation pour ${monthLabel(month)}"> <span class="unit">%</span></td><td class="money">${euro(x.total)}</td><td class="money">${euro(dueCumulative[index])}</td></tr>`}).join('') || '<tr><td colspan="6">Renseignez la date d’entrée pour créer l’échéancier.</td></tr>'; document.querySelector('#paymentMonth').innerHTML=ds.map(m=>`<option value="${m}">${monthLabel(m)}</option>`).join(''); document.querySelector('#payments').innerHTML=state.payments.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<tr><td>${new Intl.DateTimeFormat('fr-FR').format(new Date(p.date+'T12:00:00'))}</td><td>${monthLabel(p.month)}</td><td>${p.source}</td><td>${p.note||'—'}</td><td class="money">${euro(p.chargeAmount)}</td><td class="money">${euro(p.amount-p.chargeAmount)}</td><td class="money">${euro(p.amount)}</td><td><button class="small-delete delete-payment" data-id="${p.id}">Supprimer</button></td></tr>`).join('') || '<tr><td colspan="8">Aucun paiement enregistré.</td></tr>'; document.querySelector('#recap').innerHTML=ds.map((month,index)=>`<tr><td>${monthLabel(month)}</td><td class="money">${euro(dueCumulative[index])}</td><td class="money">${euro(paid(month,'Locataire'))}</td><td class="money">${euro(paid(month,'CAF'))}</td><td class="money">${euro(paid(month,'Divers'))}</td><td class="money">${euro(paidCumulative[index])}</td><td class="balance ${dueCumulative[index]-paidCumulative[index]>0?'negative':''}">${euro(dueCumulative[index]-paidCumulative[index])}</td></tr>`).join('') || '<tr><td colspan="7">L’échéancier apparaîtra ici.</td></tr>'; }
document.querySelector('#saveSettings').onclick=()=>{ storeSettingsForm(); save(); render(); };
document.querySelector('#months').onchange=event=>{ const input=event.target.closest('.coefficient-input'); if(input) setMonthCoefficient(input.dataset.month,input.value); };
document.querySelector('#paymentForm').onsubmit=event=>{ event.preventDefault(); const payment=Object.fromEntries(new FormData(event.target)); payment.amount=+payment.amount; payment.chargeAmount=+payment.chargeAmount; if(payment.chargeAmount>payment.amount)return alert('La part de charges ne peut pas dépasser le règlement.'); payment.id=crypto.randomUUID(); state.payments.push(payment); save(); event.target.reset(); event.target.date.value=isoToday(); render(); };
document.querySelector('#payments').onclick=event=>{ const button=event.target.closest('.delete-payment'); if(button){ state.payments=state.payments.filter(p=>p.id!==button.dataset.id); save(); render(); } };
document.querySelector('#reset').onclick=()=>{ if(confirm('Attention : cette action effacera toutes les données locales de QUITTANCES sur cet ordinateur. Les fichiers de sauvegarde déjà téléchargés ne seront pas supprimés. Continuer ?')){ localStorage.removeItem(key); location.reload(); } };
document.querySelector('#saveFile').onclick=downloadBackup;
document.querySelector('#restoreFile').onclick=()=>document.querySelector('#restoreInput').click();
document.querySelector('#restoreInput').onchange=async event=>{ const file=event.target.files?.[0]; event.target.value=''; if(!file)return; try{const backup=JSON.parse(await file.text());if(backup?.format!=='quittances-backup'||!backup.data?.settings||!Array.isArray(backup.data.months)||!Array.isArray(backup.data.payments))throw new Error('invalid');if(!confirm('Restaurer cette sauvegarde ? Le travail actuellement affiché sera remplacé.'))return;state=backup.data;save();render();document.querySelector('#paymentForm').date.value=isoToday();}catch{alert('Ce fichier n’est pas une sauvegarde QUITTANCES valide.');}};
document.querySelector('#paymentForm').date.value=isoToday(); render();